CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('owner','administrator','sales','reviewer','viewer','content_editor')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE geometry_revisions (id text PRIMARY KEY, source_hash text NOT NULL UNIQUE, provenance jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE draft_cells (id text PRIMARY KEY, revision_id text NOT NULL REFERENCES geometry_revisions(id), data jsonb NOT NULL, review_required boolean NOT NULL DEFAULT true);
CREATE TABLE plots (id uuid PRIMARY KEY, number text NOT NULL, block text NOT NULL, data jsonb NOT NULL, publication text NOT NULL DEFAULT 'draft' CHECK(publication IN ('draft','reviewed','published','archived')), status text NOT NULL DEFAULT 'unverified' CHECK(status IN ('unverified','available','reserved','sold','blocked')), version integer NOT NULL DEFAULT 1 CHECK(version>0), price_inr numeric CHECK(price_inr>=0), price_visible boolean NOT NULL DEFAULT false, verified_at timestamptz, verified_by uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(block,number), CHECK(publication!='published' OR verified_at IS NOT NULL), CHECK(NOT price_visible OR price_inr IS NOT NULL));
CREATE TABLE plot_geometry (plot_id uuid PRIMARY KEY REFERENCES plots(id), draft_id text NOT NULL UNIQUE REFERENCES draft_cells(id), revision_id text NOT NULL REFERENCES geometry_revisions(id));
CREATE TABLE plot_dimensions (id uuid PRIMARY KEY, plot_id uuid NOT NULL REFERENCES plots(id), name text NOT NULL, metres numeric NOT NULL CHECK(metres>0), source_text text NOT NULL, edge_index integer CHECK(edge_index>=0), source_revision text NOT NULL, reviewer_id uuid NOT NULL REFERENCES users(id), verified_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE plot_verifications (id uuid PRIMARY KEY, plot_id uuid NOT NULL REFERENCES plots(id), reviewer_id uuid NOT NULL REFERENCES users(id), evidence jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE price_records (id uuid PRIMARY KEY, plot_id uuid NOT NULL REFERENCES plots(id), amount numeric CHECK(amount>=0), visible boolean NOT NULL, changed_by uuid NOT NULL REFERENCES users(id), reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inventory_status_history (id uuid PRIMARY KEY, plot_id uuid NOT NULL REFERENCES plots(id), old_status text NOT NULL, new_status text NOT NULL, changed_by uuid NOT NULL REFERENCES users(id), reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE enquiries (id uuid PRIMARY KEY, data jsonb NOT NULL, stage text NOT NULL DEFAULT 'new' CHECK(stage IN ('new','contacted','qualified','closed')), assigned_to uuid REFERENCES users(id), notes text NOT NULL DEFAULT '', next_action_at timestamptz, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE visit_requests (id uuid PRIMARY KEY, enquiry_id uuid NOT NULL REFERENCES enquiries(id), preferred_at timestamptz NOT NULL, scheduled_at timestamptz, status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','contacted','confirmed','rescheduled','completed','cancelled')), version integer NOT NULL DEFAULT 1, CHECK(status NOT IN ('confirmed','rescheduled','completed') OR scheduled_at IS NOT NULL));
CREATE TABLE audit_logs (id uuid PRIMARY KEY, actor_id uuid REFERENCES users(id), action text NOT NULL, entity_id text NOT NULL, old_value jsonb, new_value jsonb, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION reject_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'History is append-only'; END; $$;
CREATE TRIGGER protect_audit BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER protect_status BEFORE UPDATE OR DELETE ON inventory_status_history FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER protect_verification BEFORE UPDATE OR DELETE ON plot_verifications FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER protect_price BEFORE UPDATE OR DELETE ON price_records FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TABLE idempotency (scope text NOT NULL, key text NOT NULL, request_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope,key));
CREATE TABLE rate_limits (key text PRIMARY KEY, hits integer NOT NULL, reset_at timestamptz NOT NULL);
CREATE TABLE content (id text PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('setting','amenity','media','nearby')), draft jsonb NOT NULL, published jsonb, version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE import_previews (id uuid PRIMARY KEY, actor_id uuid NOT NULL REFERENCES users(id), rows jsonb NOT NULL, errors jsonb NOT NULL, expires_at timestamptz NOT NULL, committed boolean NOT NULL DEFAULT false);
CREATE TABLE geometry_proposals (id uuid PRIMARY KEY, plot_id uuid NOT NULL REFERENCES plots(id), draft_id text NOT NULL REFERENCES draft_cells(id), expected_version integer NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), actor_id uuid NOT NULL REFERENCES users(id), reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX enquiry_created ON enquiries(created_at DESC);
CREATE INDEX public_inventory ON plots(publication,block,number);
CREATE INDEX audit_entity ON audit_logs(entity_id,created_at DESC);
